\label{prop:transport}
For every measurable set $D\subset M$ with compact closure,
\begin{equation}\label{eq:transport}
\frac{d}{dt}\mu_\theta(\Phi_t(D))
=\int_{\Phi_t(D)}D_\theta f\,\rho_\theta\,dV_g,
\end{equation}
where
\begin{equation}
\label{eq:Dtheta}
D_\theta f
:=\operatorname{div}_g f+\theta^\top\mathcal{L}_f\psi
=\rho_\theta^{-1}\operatorname{div}_g(\rho_\theta f).
\end{equation}

\label{th:design}
Let $K\subset M$ be nonempty and compact and let $\Theta\subset\mathbb{R}^p$ be a nonempty compact convex set. Then:
\begin{enumerate}
\item $q_K$ is concave on $\mathbb{R}^p$. Moreover, with $B_K:=\max_{x\in K}\|b(x)\|_2$,
\begin{equation}
\label{eq:lipschitz}
|q_K(\theta_1)-q_K(\theta_2)|\le B_K\|\theta_1-\theta_2\|_2.
\end{equation}
\item For every prescribed rate $\lambda\in\mathbb{R}$, the admissible parameter set
\begin{equation*}
\label{eq:A}
\mathcal{A}_K(\lambda):=\{\theta\in\Theta:D_\theta f(x)\le-\lambda\ \forall x\in K\}
\end{equation*}
is compact and convex, and admits the half-space representation
\begin{equation}\label{eq:halfspaces}
\mathcal{A}_K(\lambda)=\Theta\cap
\bigcap_{x\in K}\{\theta:\theta^\top b(x)\le-\lambda-a(x)\}.
\end{equation}
\item The optimal constrained margin
\begin{equation}\label{eq:qstar}
q_K^*:=\max_{\theta\in\Theta}q_K(\theta)
\end{equation}
is attained. Equivalently, $(\theta^*,q_K^*)$ solves the semi-infinite convex program
\begin{equation}\label{eq:sip}
\begin{aligned}
\text{maximize}_{\theta\in\Theta,\,\lambda\in\mathbb{R}}\quad &\lambda\\
\text{subject to}\quad &a(x)+\theta^\top b(x)+\lambda\le0,
\qquad x\in K.
\end{aligned}
\end{equation}
\item For every $\kappa_\rho\ge1$, the conditioning-restricted set
\begin{equation}\label{eq:Theta-kappa}
\Theta_{\kappa_\rho}
:=\{\theta\in\Theta:\operatorname{osc}_K(\theta^\top\psi)\le\ln\kappa_\rho\}
\end{equation}
is compact and convex. If $\Theta_{\kappa_\rho}$ is nonempty, the max-margin problem remains a convex program and attains its optimum after imposing this distortion bound.
\end{enumerate}

\label{prop:active}
Let the assumptions of Theorem~\ref{th:design} hold. A point $\bar\theta\in\Theta$ maximizes $q_K$ over $\Theta$ if and only if there exist active points $x_1,\ldots,x_m\in X(\bar\theta)$, with $m\le p+1$, and coefficients $\nu_i\ge0$, $\sum_{i=1}^m\nu_i=1$, such that
\begin{equation}\label{eq:normal-cert}
-\sum_{i=1}^m\nu_i b(x_i)\in N_{\Theta}(\bar\theta),
\end{equation}
where
$N_{\Theta}(\bar\theta)
:=\{v:v^\top(\theta-\bar\theta)\le0\ \text{for all }\theta\in\Theta\}$
is the normal cone. In particular, if $\bar\theta$ lies in the interior of $\Theta$, optimality is equivalent to the existence of active points and weights satisfying
\begin{equation}\label{eq:balance}
\sum_{i=1}^m\nu_i b(x_i)=0.
\end{equation}

\label{prop:minimax}
Under the assumptions of Theorem~\ref{th:design},
\begin{equation}\label{eq:minimax-dual}
q_K^*=\min_{(A,B)\in\mathcal C_K}
\big[-A+\sigma_{\Theta}(-B)\big].
\end{equation}
The minimum is attained. Moreover, for any primal optimizer $\theta^*$, an optimal pair $(A^*,B^*)$ admits a representation
\begin{equation}\label{eq:finite-dual-support}
(A^*,B^*)=\sum_{i=1}^m\nu_i\big(a(x_i),b(x_i)\big),
~~~ m\le p+2,
\end{equation}
with $x_i\in X(\theta^*)$, $\nu_i>0$, and $\sum_i\nu_i=1$.

\label{prop:grid}
Assume $K$ is a compact metric space and, on $K$,
\[
|a(x)-a(y)|\le L_a d(x,y),~~~
\|b(x)-b(y)\|_2\le L_b d(x,y).
\]
Let $\varepsilon>0$ and let $G_\varepsilon\subset K$ be a finite $\varepsilon$-net. Then, for every $\theta\in\mathbb{R}^p$,
\begin{equation}\label{eq:grid-bound}
\begin{split}
q_K(\theta)\ge{}&
\min_{z\in G_\varepsilon}[-a(z)-\theta^\top b(z)]\\
&-(L_a+\|\theta\|_2L_b)\varepsilon.
\end{split}
\end{equation}
Consequently, if
\begin{equation}\label{eq:grid-cert}
a(z)+\theta^\top b(z)
\le-\lambda-(L_a+\|\theta\|_2L_b)\varepsilon
\end{equation}
for all $z\in G_\varepsilon$, then $D_\theta f\le-\lambda$ on all of $K$.

\label{rem:constraint}
Without a restriction on $\theta$, the supremum of $q_K(\theta)$ need not be finite. For example, if a scalar $b(x)=\mathcal{L}_f\psi(x)$ is uniformly positive on $K$, then $q_K(\alpha)\to+\infty$ as $\alpha\to-\infty$. This does not represent arbitrarily fast physical contraction of trajectories. It reflects an increasingly distorted reference measure. A compact design set $\Theta$ therefore has both a mathematical and an interpretive role.

One useful additional restriction is a bound on density conditioning,
\begin{equation}\label{eq:conditioning}
\frac{\max_K\rho_\theta}{\min_K\rho_\theta}
=\exp\!\big(\operatorname{osc}_K(\theta^\top\psi)\big)\le\kappa_\rho.
\end{equation}
As shown in Theorem~\ref{th:design}, \eqref{eq:conditioning} is a convex constraint. It does not, in general, make the parameter set compact: multiplication of a density by a positive constant leaves $D_\theta f$ unchanged, and redundant basis directions may therefore remain unbounded. Thus \eqref{eq:conditioning} should be combined with a compact box or ellipsoid, or with an explicit normalization that removes such gauge directions.

\label{cor:alpha}
Let $K$ be nonempty and compact and let $w>0$ be $C^1$ on a neighborhood of $K$. Set
\[
a(x)=\operatorname{div}_gf(x),\qquad b(x)=\mathcal{L}_f\ln w(x).
\]
For a prescribed $\lambda\in\mathbb{R}$, define the extended-real bounds
\begin{align*}
L_\lambda&:=\sup_{\{x\in K:b(x)<0\}}
\frac{-\lambda-a(x)}{b(x)}\in[-\infty,+\infty],\notag\\
U_\lambda&:=\inf_{\{x\in K:b(x)>0\}}
\frac{-\lambda-a(x)}{b(x)}\in[-\infty,+\infty],\label{eq:LU}
\end{align*}
with $L_\lambda=-\infty$ when $\{b<0\}$ is empty and $U_\lambda=+\infty$ when $\{b>0\}$ is empty. If
\begin{equation}\label{eq:zero-compat}
a(x)\le-\lambda\qquad\text{whenever }b(x)=0,
\end{equation}
then the set of \emph{finite} admissible exponents is exactly
\begin{equation}\label{eq:alpha-interval}
\begin{split}
\mathcal I_\lambda
&:=\{\alpha\in\mathbb{R}:D_\alpha f\le-\lambda\text{ on }K\}\\
&=\{\alpha\in\mathbb{R}:L_\lambda\le\alpha\le U_\lambda\}.
\end{split}
\end{equation}
If \eqref{eq:zero-compat} fails, then $\mathcal I_\lambda=\varnothing$. Under \eqref{eq:zero-compat}, the set in \eqref{eq:alpha-interval} is nonempty if and only if
\begin{equation}\label{eq:interval-nonempty}
L_\lambda\le U_\lambda,\qquad
L_\lambda<+\infty,\qquad U_\lambda>-\infty.
\end{equation}
For a constrained interval $\Theta=[\alpha_{\min},\alpha_{\max}]$, the feasible exponents are $\mathcal I_\lambda\cap\Theta$.

\label{th:contraction}
If, for some $\theta$ and $\lambda>0$,
\begin{equation}\label{eq:Dnegative}
D_\theta f(x)\le-\lambda,\qquad x\in K,
\end{equation}
then every measurable set $D\subset K$ satisfies
\begin{equation}\label{eq:exp-contract}
\mu_\theta(\Phi_t(D))\le e^{-\lambda t}\mu_\theta(D),
\qquad t\ge0.
\end{equation}
In particular, any $\theta\in\mathcal{A}_K(\lambda)$ from Theorem~\ref{th:design} certifies the rate $\lambda$.

\label{rem:nullsets}
On compact $K$, the positive continuous density satisfies
$0<m_\theta\le\rho_\theta\le M_\theta<\infty$. Hence, for measurable $E\subset K$,
\begin{equation}\label{eq:equivmeas}
m_\theta\operatorname{vol}_g(E)\le\mu_\theta(E)\le M_\theta\operatorname{vol}_g(E).
\end{equation}
Therefore weighted and Riemannian measures have exactly the same null sets on $K$. The value of density shaping is not a new notion of ``zero volume'' on compact regions. It is the possibility of obtaining a useful sign and rate in the transport equation when the ordinary divergence does not provide one.

\label{prop:invariant}
Let $O\subset M$ be open. Suppose $D_\theta f\le0$ on $O$ and the set
$\{x\in O:D_\theta f(x)<0\}$ is dense in $O$. Then every compact Jordan-measurable set $A\subset O$ satisfying $\Phi_t(A)=A$ for all $t\ge0$ satisfies
\begin{equation*}
\label{eq:zero-measure}
\mu_\theta(A)=\operatorname{vol}_g(A)=0.
\end{equation*}

\label{th:discrete}
For every measurable $D\subset K$,
\begin{equation}\label{eq:change-map}
\mu_\theta(P(D))=\int_D J_\theta P(x)\rho_\theta(x)\,dV_g(x).
\end{equation}
If, for some $\gamma>0$,
\begin{equation}\label{eq:disc-cond}
\ell_\theta(x)\le-\gamma,\qquad x\in K,
\end{equation}
then
\begin{equation}\label{eq:disc-contract}
\mu_\theta(P^k(D))\le e^{-k\gamma}\mu_\theta(D),
\qquad k\in\mathbb N.
\end{equation}
Moreover, the discrete design margin
\begin{equation*}
\label{eq:qP}
q_K^P(\theta):=\min_{x\in K}[-\ell_\theta(x)]
\end{equation*}
is concave and Lipschitz, and maximizing it over a compact convex $\Theta$ is again a semi-infinite convex program.

\label{cor:discrete-invariant}
Under the hypotheses of Theorem~\ref{th:discrete}, suppose a compact measurable set $B\subset K$ satisfies $P(B)\subseteq B$ and \eqref{eq:disc-cond}. Then
\begin{equation*}\label{eq:Ainf}
A_\infty:=\bigcap_{k=0}^{\infty}P^k(B)
\end{equation*}
has $\mu_\theta(A_\infty)=0$ and, consequently, $\operatorname{vol}_g(A_\infty)=0$.

\label{th:distance}
Assume $U$ is positively invariant and, for some $\lambda>0$,
\begin{equation}\label{eq:moment-cond}
\mathcal{L}_f\delta_N(x)+\delta_N(x)D_\theta f(x)
\le-\lambda\delta_N(x),
\qquad x\in U.
\end{equation}
Then every measurable $D\Subset U$ satisfies
\begin{equation}\label{eq:moment-contract}
\mathcal M_{N,\theta}(\Phi_t(D))
\le e^{-\lambda t}\mathcal M_{N,\theta}(D).
\end{equation}
If, independently,
\begin{equation}\label{eq:pointwise-distance}
\mathcal{L}_f\delta_N\le-2\eta\delta_N
\quad\text{on }U
\end{equation}
for some $\eta>0$, then
\begin{equation}\label{eq:distance-exp}
\operatorname{dist}_g(\Phi_t(x),N)
\le e^{-\eta t}\operatorname{dist}_g(x,N),\qquad x\in U.
\end{equation}

\label{prop:conformal}
The Riemannian volume form of $\widetilde g_\theta$ is
\begin{equation}\label{eq:vol-conformal}
dV_{\widetilde g_\theta}=\rho_\theta\,dV_g,
\end{equation}
and
\begin{equation}\label{eq:div-conformal}
\operatorname{div}_{\widetilde g_\theta}f
=\operatorname{div}_gf+\mathcal{L}_f\ln\rho_\theta
=D_\theta f.
\end{equation}
Thus weighted phase-volume contraction in $(M,g)$ is ordinary Riemannian volume contraction in the conformal metric $\widetilde g_\theta$.
